89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper) {
91	        this.clinicService = clinicService;
92	        this.ownerMapper = ownerMapper;
93	        this.petMapper = petMapper;
94	        this.visitMapper = visitMapper;
